export function previewValue(value) {
  if(value===null||value===undefined)return '—';
  if(Array.isArray(value))return value.map(previewValue).join(', ');
  if(typeof value==='object')return value.name??value.label??value.key??value.id??JSON.stringify(value);
  return String(value);
}
export function recordPage(items,{query='',page=0,size=20,columns=[]}={}) {
  const search=query.trim().toLocaleLowerCase();
  const matched=search?items.filter(item=>columns.some(column=>previewValue(column.value?column.value(item):item[column.key]).toLocaleLowerCase().includes(search))):items;
  const pages=Math.max(1,Math.ceil(matched.length/size));
  const current=Math.max(0,Math.min(page,pages-1));
  return {items:matched.slice(current*size,(current+1)*size),total:matched.length,page:current,pages,
    from:matched.length?current*size+1:0,to:Math.min((current+1)*size,matched.length)};
}
export function previewCatalog(document) {
  const statuses=new Map(document.statuses.map(row=>[row.id,row.name]));
  const users=new Map(document.users.map(row=>[row.id,row.name+' <'+row.email+'>']));
  const labels=new Map(document.labels.map(row=>[row.id,row.name]));
  const issues=new Map(document.issues.map(row=>[row.id,'#'+row.number+' '+row.title]));
  const ref=id=>issues.get(id)??document.externalIssues?.find(row=>row.id===id)?.key??id??'—';
  return {
    issues:{label:'Issues',items:document.issues,columns:[{key:'number',label:'Number'},{key:'title',label:'Title'},{key:'statusId',label:'Status',value:row=>statuses.get(row.statusId)},
      {key:'assigneeId',label:'Assignee',value:row=>users.get(row.assigneeId)??'Unassigned'},{key:'parentId',label:'Parent',value:row=>ref(row.parentId)},
      {key:'labelIds',label:'Labels',value:row=>row.labelIds.map(id=>labels.get(id))},{key:'description',label:'Description'},{key:'estimate',label:'Estimate'},{key:'dueDate',label:'Due date'}]},
    comments:{label:'Comments',items:document.comments,columns:[{key:'issueId',label:'Issue',value:row=>ref(row.issueId)},{key:'authorId',label:'Author',value:row=>users.get(row.authorId)},{key:'body',label:'Comment'},{key:'createdAt',label:'Created'}]},
    labels:{label:'Labels',items:document.labels,columns:[{key:'name',label:'Name'},{key:'color',label:'Color'}]},
    relations:{label:'Relations',items:document.relations,columns:[{key:'sourceIssueId',label:'From',value:row=>ref(row.sourceIssueId)},{key:'kind',label:'Relation'},{key:'targetIssueId',label:'To',value:row=>ref(row.targetIssueId)}]},
    statuses:{label:'Workflow',items:document.statuses,columns:[{key:'position',label:'Order'},{key:'name',label:'Name'},{key:'category',label:'Category'}]},
    users:{label:'People',items:document.users,columns:[{key:'name',label:'Name'},{key:'email',label:'Email'}]},
    externalIssues:{label:'External links',items:document.externalIssues??[],columns:[{key:'key',label:'Key'},{key:'title',label:'Title'},{key:'projectId',label:'Original project'}]}
  };
}

import {useState} from 'preact/hooks';
import {Button,Empty} from '../../components/ui.jsx';
import {recordPage,previewValue,previewCatalog} from './record-browser-state.js';
export function RecordPager({items,columns,label,renderRow,size=20}) {
  const [query,setQuery]=useState(''),[page,setPage]=useState(0);
  const result=recordPage(items,{query,page,size,columns});
  return <section className="record-pager" aria-label={label}>
    <label>Search {label.toLowerCase()} <input type="search" value={query} onInput={event=>{setQuery(event.currentTarget.value);setPage(0);}}/></label>
    <p role="status">Showing {result.from}–{result.to} of {result.total} {label.toLowerCase()}.</p>
    {!result.items.length?<Empty>No matching {label.toLowerCase()}.</Empty>:renderRow?<div>{result.items.map(item=><div className="mapping-row" key={item.id}>{renderRow(item)}</div>)}</div>:
      <div className="table-scroll"><table><thead><tr>{columns.map(column=><th key={column.key} scope="col">{column.label}</th>)}</tr></thead>
        <tbody>{result.items.map((item,index)=><tr key={item.id??index}>{columns.map(column=>{
          const value=previewValue(column.value?column.value(item):item[column.key]);
          return <td key={column.key}>{value.length>160?<details><summary>{value.slice(0,120)}…</summary><pre>{value}</pre></details>:value}</td>;
        })}</tr>)}</tbody>
      </table></div>}
    <div className="pagination"><Button type="button" disabled={result.page===0} onClick={()=>setPage(0)}>First {label.toLowerCase()}</Button>
      <Button type="button" disabled={result.page===0} onClick={()=>setPage(result.page-1)}>Previous {label.toLowerCase()}</Button>
      <span>Page {result.page+1} of {result.pages}</span>
      <Button type="button" disabled={result.page+1>=result.pages} onClick={()=>setPage(result.page+1)}>Next {label.toLowerCase()}</Button>
      <Button type="button" disabled={result.page+1>=result.pages} onClick={()=>setPage(result.pages-1)}>Last {label.toLowerCase()}</Button>
    </div>
  </section>;
}
export function DocumentBrowser({document}) {
  const [kind,setKind]=useState('issues');
  const catalog=previewCatalog(document),selected=catalog[kind];
  return <section><h3>Included records</h3><label>Record type <select value={kind} onChange={event=>setKind(event.currentTarget.value)}>{Object.entries(catalog).map(([key,group])=><option key={key} value={key}>{group.label} ({group.items.length})</option>)}</select></label>
    <RecordPager key={kind} items={selected.items} columns={selected.columns} label={selected.label}/>
  </section>;
}

export function createRequestGuard() {
  let revision=0;
  let controller=null;
  return {
    invalidate(){revision++;controller?.abort();controller=null;},
    begin(){controller?.abort();controller=new AbortController();return {revision,controller,signal:controller.signal};},
    current(ticket){return Boolean(ticket&&ticket.revision===revision&&ticket.controller===controller&&!ticket.signal.aborted);},
    revision(){return revision;}
  };
}
export function guardedResult(guard,ticket,apply,value) {
  if(!guard.current(ticket))return false;
  apply(value);
  return true;
}
